There exist standard integers $D, L \geqslant 1$, shifts $h_1,\dots,h_L \in \mathbb{Z}^2$, and a set $\Omega \subset \{-1,1\}^{DL}$ such that the question of whether there exist functions $f_d \colon \mathbb{Z}^2 \to \{-1,1\}$, $d=1,\dots,D$ that solve the constraint
\begin{equation}
(f_d(n+h_l))_{d=1,\dots,D; l=1,\dots,L} \in \Omega 
\end{equation}
for all $n \in \mathbb{Z}^2$ is undecidable (when expressed as a first-order sentence in ZFC).

There exist standard integers $D_0 \geqslant 2$ and $M_1,M_2 \geqslant 1$, shifts $h_1,\dots,h_{D_0} \in \mathbb{Z}^2$, and vectors $\epsilon_j^{(m)} \in \{-1,1\}^{D}$ for $j=1,2$ and $m=1,\dots,M_j$ such that the question of whether there exist functions $f_{j,d} \colon \mathbb{Z}^2 \to \{-1,1\}$, for $j=1,2$, $d=1,\dots,D_0$ that solve the constraints
\begin{equation}
(f_{j,d}(n))_{d=1,\dots,D_0} \not \in \{ -\epsilon_j^{(m)}, \epsilon_j^{(m)} \}
\end{equation}
for all $n \in \mathbb{Z}^2$, $j=1,2$, $m =1,\dots,M_j$, as well as the constraints
\begin{equation}
f_{2,d}(n+h_d) = - f_{1,d}(n)
\end{equation}
for all $n \in \mathbb{Z}^2$ and  $d = 1,\dots,D_0$, is undecidable (when expressed as a first-order sentence in ZFC).

There exist  standard integers $D \geqslant D_0 \geqslant 1$ and $M_1, M_2 \geqslant 1$, integer coefficients $a_{j,d}^{(m)} \in \mathbb{Z}$ for $j=1,2$, $d=1,\dots,D$, $m=1,\dots,M_j$, and shifts $h_d \in \mathbb{Z}^2$ for $d=1,\dots,D_0$ such that the question of whether there exist functions $f_{j,d} \colon \mathbb{Z}^2 \to \{-1,1\} \subset \mathbb{Z}$ for $j=1,2$ and $d=1,\dots,D$ that solve
the system of linear functional equations
\begin{equation}
\sum_{d=1}^D a_{j,d}^{(m)} f_{j,d}(n) = 0
\end{equation}
for all $n \in \mathbb{Z}^2$, $j=1,2$, and $m = 1,\dots,M_j$, as well as the system of linear functional equations
\begin{equation}
f_{2,d}(n+h_d) = - f_{1,d}(n)
\end{equation}
for all $n \in \mathbb{Z}^2$ and $d=1,\dots,D_0$, is undecidable (when expressed as a first-order sentence in ZFC).

There exist  standard integers $N > 2$ and $D,M \geqslant 1$, and for each $m=1,\dots,M$ there exist shifts $h_1^{(m)}, h_2^{(m)} \in \mathbb{Z}^2$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset \mathbb{Z}_N^D$ for $m=1,\dots,M$ such that the question of whether there exist functions $f_1,f_2 \colon \mathbb{Z}^2 \to \{-1,1\}^D$ that solve
the system of functional equations
\begin{equation}
(F_1^{(m)} + \epsilon f_1(n+h_1^{(m)})) \uplus
(F_2^{(m)} + \epsilon f_2(n+h_2^{(m)})) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2$, $m=1,\dots,M$, and $\epsilon=\pm 1$ is undecidable (when expressed as a first-order sentence in ZFC).

There exists an explicit finite abelian group $G_0$, a standard integer $M \geqslant 1$, and for each $m=1,\dots,M$ there exist (possibly empty) finite subsets $H_1^{(m)}, H_2^{(m)}$ of $\mathbb{Z}^2 \times \mathbb{Z}_2$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset G_0$ for $m=1,\dots,M$ such that the question of whether there exist  functions $f_1,f_2 \colon \mathbb{Z}^2 \times \mathbb{Z}_2 \to G_0$ that solve
the system of functional equations
\begin{equation}
\biguplus_{h_1 \in H_1^{(m)}} (F_1^{(m)} + f_1(n+h_1)) \uplus
\biguplus_{h_2 \in H_2^{(m)}} (F_2^{(m)} + f_2(n+h_2)) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2\times \mathbb{Z}_2$ and $m=1,\dots,M$ is undecidable (when expressed as a first-order sentence in ZFC).

There exists an explicit finite abelian group $G_0$, a standard integer $M \geqslant 1$, and for each $m=1,\dots,M$ there exist (possibly empty) finite subsets $H_1^{(m)}, H_2^{(m)}$ of $\mathbb{Z}^2 \times \mathbb{Z}$ and (possibly empty sets) $F_1^{(m)}, F_2^{(m)}, E^{(m)} \subset G_0$ for $m=1,\dots,M$ such that the question of whether there exist  functions $g_1,g_2 \colon \mathbb{Z}^2 \times \mathbb{Z} \to G_0$ that solve
the system of functional equations
\begin{equation}
\biguplus_{h_1 \in H_1^{(m)}} (F_1^{(m)} + g_1(n+h_1)) \uplus
\biguplus_{h_2 \in H_2^{(m)}} (F_2^{(m)} + g_2(n+h_2)) = E^{(m)}
\end{equation}
for all $n \in \mathbb{Z}^2\times \mathbb{Z}$ and $m=1,\dots,M$ is undecidable (when expressed as a first-order sentence in ZFC).

Let $D \geqslant D_0 \geqslant 1$ and $M_1, M_2 \geqslant 1$ be natural numbers, and let  $a_{j,d}^{(m)} \in \mathbb{Z}$ be integer coefficients for $j=1,2$, $d=1,\dots,D$, $m=1,\dots,M_j$, and shifts $h_d \in \mathbb{Z}^2$ for $d=1,\dots,D_0$.  Let $N$ be a multiple of $4$ that is sufficiently large depending on all previous data.  We  define the coordinate projections
\begin{align*}
\pi'_1,\dots,\pi'_D &\colon (\mathbb{Z}_N^2)^D \to \mathbb{Z}_N^2 \\
\pi''_1,\dots,\pi''_{D} &\colon (S_{\mathbb{Z}_4^2})^{D} \to S_{\mathbb{Z}_4^2} \\
\pi'''_1, \pi'''_2 &\colon \mathbb{Z}_N^2 \to \mathbb{Z}_N
\end{align*}
in the obvious fashion, while also letting $\Pi \colon \mathbb{Z}_N^2 \to \mathbb{Z}_4^2$ be the reduction mod $4$ map, which is a homomorphism with kernel $(4\mathbb{Z}_N)^2$; see Figure fig:maps.  
Then the following statements are equivalent:
\begin{itemize}
\item[(i)]  There exist functions $f_{j,d} \colon \mathbb{Z}^2 \to \{-1,1\} \subset \mathbb{Z}$ for $j=1,2$ and $d=1,\dots,D$ that solve
the system of linear functional equations (1.9) for all $n \in \mathbb{Z}^2$, $j=1,2$, and $m = 1,\dots,M_j$, as well as the system of linear functional equations (1.10) for all $n \in \mathbb{Z}^2$ and $d=1,\dots,D_0$.
\item[(ii)]  There exists a set $A \subset \mathbb{Z}^2 \times \mathbb{Z}_2 \times (\mathbb{Z}_N^2)^D \times (S_{\mathbb{Z}_4^2})^D$ that simultaneously solves the following systems of nonabelian tiling equations:

\begin{itemize}
    \item[1. ] The tiling equations \begin{equation}
 \operatorname{Tile}( \{((0,0),0)\} \times H_j^{(m)} \times C_\sigma  ; \mathbb{Z}^2 \times \mathbb{Z}_2 \times H_j^{(m)} \times S_{\mathbb{Z}_4^2}^{D} )
\end{equation}
for all $j=1,2$ and $m=1,\dots,M_j$, and cycles $\sigma \in S_{\mathbb{Z}_4^2}$, where $H_j^{(m)} \leqslant (\mathbb{Z}_N^2)^D$ is the subgroup
\begin{equation}
H_{j}^{(m)} \coloneqq \left\{ (y_{1,d},y_{2,d})_{d=1}^D \in (\mathbb{Z}_N^2)^D: \sum_{d=1}^D a_{j,d}^{(m)} y_{j,d} = 0 \right\}
\end{equation}
and $C_\sigma \subset S_{\mathbb{Z}_4^2}^{D}$ is the set
$$ C_\sigma \coloneqq (\pi''_1)^{-1}(\{0, \sigma, \dots, 15 \sigma \}) = \{0, \sigma, \dots, 15 \sigma \} \times S_{\mathbb{Z}_4^2}^{D-1}.$$
\item[2. ] The  tiling equations
\begin{equation}
\begin{split}
&\operatorname{Tile}( \{(0,0)\} \times \mathbb{Z}_2 \times (\pi'''_j \circ \pi'_d)^{-1}(\{0\}) \times C_\sigma  ; \\
&\quad\quad \mathbb{Z}^2 \times \mathbb{Z}_2 \times (\pi'''_j \circ \pi'_d)^{-1}(\{-1,1\}) \times S_{\mathbb{Z}_4^2}^{D} )
\end{split}
\end{equation}
for all $d=1,\dots,D$, $j=1,2$, and cycles $\sigma \in S_{\mathbb{Z}_4^2}$. 
\item[3. ] The  tiling equations
\begin{equation}
\operatorname{Tile}( (T_d \uplus T'_d)  ; \mathbb{Z}^2 \times \mathbb{Z}_2 \times (\mathbb{Z}_N^2)^D \times (\pi''_d)^{-1}(B) )
\end{equation}
for all $d=1,\dots,D_0$, where 
\begin{align*}
T_d &\coloneqq
\{ ((0,0), 0)\} \times (\mathbb{Z}_N^2)^D \times (\pi''_d)^{-1}(\tau(K))\\
T'_d &\coloneqq \{(-h_d,0)\} \times (\mathbb{Z}_N^2)^D \times (\pi''_d)^{-1}(\rho + \tau(K)).
\end{align*}
\item[4. ] The  tiling equations
\begin{equation}
\operatorname{Tile}( \{((0,0),0)\} \times F_{\ell,d}  ; \mathbb{Z}^2 \times \mathbb{Z}_2 \times  E_{\ell,d} )
\end{equation}
for all $d=1,\dots,D$ and $\ell=1,\dots,L$, where
\begin{align*}
F_{\ell,d} &\coloneqq \{ (y,\zeta) \in (\mathbb{Z}_N^2)^D \times S_{\mathbb{Z}_4^2}^{D}: (\pi''_d(\zeta), \Pi(\pi'_d(y))) \in F_\ell \} \\
E_{\ell,d} &\coloneqq \{ (y,\zeta) \in (\mathbb{Z}_N^2)^D \times S_{\mathbb{Z}_4^2}^{D}: (\pi''_d(\zeta), \Pi(\pi'_d(y))) \in E_\ell \}
\end{align*}
and $F_\ell, E_\ell$ are the sets from (11.10).
\end{itemize}
\end{itemize}

Let $G$ be an explicit finitely generated abelian group, let $G_1$ be an explicit finite abelian group, let $J, M \geqslant 1$ and $N > J$ be standard natural numbers, and suppose that for each $j=1,\dots,J$ and $m=1,\dots,M$ one is given a (possibly empty) finite subset $H_j^{(m)}$ of $G$ and a (possibly empty) subset $F_j^{(m)}$ of $G_1$.  For each $m=1,\dots,M$, assume also that we are given a subset $E^{(m)}$ of $G_1$.  We adopt the abbreviations
\begin{align*}
    [[a]] &\coloneqq \{a\} \times G_1 \subset \mathbb{Z}_N \times G_1 \\
    [[a,b]] &\coloneqq \{ n \in \mathbb{Z}: a\leqslant n \leqslant b\} \times G_1\subset \mathbb{Z}_N\times G_1
\end{align*} 
for integers $a \leqslant b$.  Then the following are equivalent:
\begin{itemize}
\item[(i)]  The system of tiling equations
\begin{equation}
\operatorname{Tile}\left( \left( -H_j^{(m)} \times \{0\} \times F_j^{(m)} \uplus \{0\} \times [[j]])\right)_{j=1}^J; G \times (\{0\} \times E^{(m)} \uplus [[1,J]]) \right)
\end{equation}
for all $m=1,\dots,M$, together with the tiling equations
\begin{equation}
\operatorname{Tile}\left( \left( \{0\} \times [[\sigma(j)]] \right)_{j=1}^J; G \times [[1,J]] \right)
\end{equation}
for every permutation $\sigma \colon \{1,\dots,J\} \to \{1,\dots,J\}$ of $\{1,\dots,J\}$, admit a solution.
\item[(ii)]  There exist $f_j \colon G \to G_1$ for $j=1,\dots,J$ that obey the system of functional equations
\begin{equation}
\biguplus_{j=1}^J \biguplus_{h_j \in H_j^{(m)}} (F_j^{(m)} + f_j(n+h_j)) = E^{(m)} 
\end{equation}
for all $n \in G$ and $m=1,\dots,M$.
\end{itemize}

Let $G$ be an explicitly finitely generated abelian group, and $G_1=\mathbb{Z}_{N_1}\times\dots\times \mathbb{Z}_{N_k}$ be an explicit finite abelian group with $N_1,\dots,N_k \geqslant 5$. Let $J,M \geqslant 1$ be standard natural numbers, and $\Lambda, R$ be as in 9.3.
Suppose that for each $j=1,\dots,J$ and $m=1,\dots,M$ one is given a (possibly empty) finite subset $H_j^{(m)}$ of $G$ and a (possibly empty) subset $F_j^{(m)}$ of $\mathbb{Z}^k$.  For each $m=1,\dots,M$, assume also that we are given a subset $E_1^{(m)}$ of $G_1$ and let $E^{(m)} \coloneqq \pi^{-1}(E_1^{(m)})$, where $\pi \colon \mathbb{Z}^k \to G_1$ is the quotient homomorphism (with kernel $\Lambda$).
 We adopt the abbreviations
$$ [[a]] \coloneqq \{a\} \times R ; \quad [[a,b]] \coloneqq  \{ n \in \mathbb{Z}: a\leqslant n \leqslant b\} \times R \subset \mathbb{Z}\times \mathbb{Z}^k $$
for integers $a \leqslant b$.  Let $N>J$. Then the following are equivalent:
\begin{itemize}
\item[(i)]  The system of tiling equations
\begin{equation}
\operatorname{Tile}\left( \left( -H_j^{(m)} \times \{0\} \times F_j^{(m)} \uplus \{0\} \times [[j]])\right)_{j=1}^J; \tilde E^{(m)} \right)
\end{equation}
for all $m=1,\dots,M$, together with the tiling equations
\begin{equation}
\operatorname{Tile}\left( \left( \{0\} \times [[\sigma(j)]] \right)_{j=1}^J; G \times ([[1,J]]\oplus N\mathbb{Z}\times\Lambda ) \right)
\end{equation}
for every permutation $\sigma \colon \{1,\dots,J\} \to \{1,\dots,J\}$ of $\{1,\dots,J\}$, admit a solution, where
$$ \tilde E^{(m)} \coloneqq G \times (N\mathbb{Z} \times E^{(m)} \uplus [[1,J]] \oplus N\mathbb{Z}\times \Lambda ).$$
\item[(ii)]  There exist $f_j \colon G \to G_1$ for $j=1,\dots,J$ that obey the system of functional equations
\begin{equation}
\biguplus_{j=1}^J \biguplus_{h_j \in H_j^{(m)}} (F_j^{(m)} + f_j(n+h_j)) = E_1^{(m)} 
\end{equation}
for all $n \in G$ and $m=1,\dots,M$.
\end{itemize}

Let $J,M \geqslant 1$, let $G = \mathbb{Z}^d \times G_0$ be an explicit finitely generated abelian group for some explicit finite abelian group $G_0$.  Let $\mathbb{Z}_N$ be a cyclic group with $N>M$, and for each $m=1,\dots,M$ let $F_1^{(m)},\dots,F_J^{(m)}$ be finite non-empty subsets of $G$ and $E_0^{(m)}$ a subset of $G_0$.  Define the finite sets $\tilde F_1,\dots,\tilde F_J \subset G \times \mathbb{Z}_N$ and the set $\tilde E_0 \subset G_0 \times \mathbb{Z}_N$ by 
\begin{equation}
 \tilde F_j \coloneqq \biguplus_{m=1}^M F_j^{(m)} \times \{m\}
 \end{equation}
and
\begin{equation}
 \tilde E_0 \coloneqq \biguplus_{m=1}^M E_0^{(m)} \times \{m\}.
 \end{equation}
\begin{itemize}
\item[(i)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; \mathbb{Z}^d \times E_0^{(m)}), m=1,\dots,M$ of tiling equations is aperiodic if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \mathbb{Z}^d \times \tilde E_0)$ is aperiodic.
\item[(ii)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; \mathbb{Z}^d \times E_0^{(m)}), m=1,\dots,M$ of tiling equations is undecidable if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \mathbb{Z}^d \times \tilde E_0)$ is undecidable.
\end{itemize}

Let $J,M,d \geqslant 1$ and $N>M$ be standard natural numbers.  
For each $m=1,\dots,M$, let $F_1^{(m)},\dots,F_J^{(m)}$ be finite non-empty subsets of $\mathbb{Z}^d$, and let $E^{(m)}$ be a periodic subset of $\mathbb{Z}^d$.  Define the finite sets $\tilde F_1,\dots,\tilde F_J \subset \mathbb{Z}^d \times \{1,\dots, M\}$ and the periodic set $\tilde E \subset \mathbb{Z}^d \times \mathbb{Z}$ by 
\begin{equation}
 \tilde F_j \coloneqq \biguplus_{m=1}^M F_j^{(m)} \times \{m\}
 \end{equation}
and
\begin{equation}
 \tilde E \coloneqq  \biguplus_{m=1}^M E^{(m)} \times (N\mathbb{Z}+m ).
 \end{equation}
\begin{itemize}
\item[(i)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; E^{(m)}), m=1,\dots,M$ of tiling equations is aperiodic if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \tilde E)$ is aperiodic.
\item[(ii)]  The system $\operatorname{Tile}(F_1^{(m)},\dots,F_J^{(m)}; E^{(m)}), m=1,\dots,M$ of tiling equations is undecidable if and only if the tiling equation
$\operatorname{Tile}(\tilde F_1,\dots,\tilde F_J; \tilde E)$ is undecidable.
\end{itemize}
